templates.00:
table netdev syswarden_hw_drop {
	set syswarden_blacklist {
		type ipv4_addr
		flags interval
		auto-merge
	}

	set syswarden_whitelist {
		type ipv4_addr
		flags interval
		auto-merge
	}

	set syswarden_whitelist6 {
		type ipv6_addr
		flags interval
		auto-merge
	}

	chain ingress_frontline {
		type filter hook ingress device {{interface}} priority -500; policy accept;
		ip saddr @syswarden_whitelist accept
		ip6 saddr @syswarden_whitelist6 accept
		ip protocol tcp tcp flags ! fin,syn,rst,psh,ack,urg counter packets 0 bytes 0 drop
		ip protocol tcp tcp flags & (fin | syn | rst | psh | ack | urg) == fin | syn | rst | psh | ack | urg counter packets 0 bytes 0 drop
		ip protocol tcp tcp flags & (fin | syn) == fin | syn counter packets 0 bytes 0 drop
		ip protocol tcp tcp flags & (syn | rst) == syn | rst counter packets 0 bytes 0 drop
		ip saddr @syswarden_blacklist limit rate 2/second burst 5 packets log prefix "[SysWarden-BLOCK] "
		ip saddr @syswarden_blacklist drop
	}
}

